<?php require 'config.php'; $q=trim($_GET['q']??'');$stmt=$pdo->prepare('SELECT * FROM tours WHERE active=1 AND (title LIKE ? OR location LIKE ?) ORDER BY id DESC');$stmt->execute(['%'.$q.'%','%'.$q.'%']);$tours=$stmt->fetchAll();require 'header.php';?><section class="page-head"><h1>Available Tours</h1><p>Search and choose a tour in Ha'il.</p></section><form method="get" class="search"><label for="q">Search tours or locations</label><div class="searchrow"><input id="q" name="q" value="<?=e($q)?>" placeholder="e.g. Aja"><button class="btn">Search</button></div></form><div class="cards"><?php foreach($tours as $t): ?><article class="card"><div class="emoji">⛰️</div><p class="eyebrow"><?=e($t['location'])?></p><h3><?=e($t['title'])?></h3><p><?=e($t['description'])?></p><p><strong><?=e($t['price'])?> SAR</strong> per visitor</p><a class="btn" href="tour.php?id=<?=$t['id']?>">View Details</a></article><?php endforeach;?></div><?php if(!$tours):?><p>No tours found. Try another search.</p><?php endif;require 'footer.php';?>